                    remove_delta = dist(prev1, next1) - dist(prev1, c) - dist(c, next1)
                    for pos2 in range(len(r2) + 1):
                        prev2 = depot if pos2 == 0 else r2[pos2 - 1]
                        next2 = depot if pos2 == len(r2) else r2[pos2]
                        insert_delta = dist(prev2, c) + dist(c, next2) - dist(prev2, next2)
                        gain = remove_delta - insert_delta
                        cand = (gain, i, pos1, j, pos2)
                        if best_move is None or cand > best_move:
                            best_move = cand

        if best_move is not None and best_move[0] > 1e-12:
            _, i, pos1, j, pos2 = best_move
            c = routes[i].pop(pos1)
            routes[j].insert(pos2, c)
            # clean empty routes
            routes = [r for r in routes if r]
            routes = [two_opt(r) for r in routes]
            improved = True

    # Final cleanup: remove any empty routes
    routes = [r for r in routes if r]

    # Safety: ensure all customers exactly once; if anything is off, rebuild deterministically.
    flat = []
    for r in routes:
        flat.extend(r)
    if sorted(flat) != sorted(customers):
        # deterministic fallback rebuild: simple sweep by polar-like order if coords available, else id order
        if coords is not None:
            # sort by angle approximation via quadrant and slope without imports
            def key(c):
                p = coords[c] if isinstance(coords, dict) else coords[c]
                return (p[1] < 0, 0 if p[0] >= 0 else 1, p[1] / (abs(p[0]) + abs(p[1]) + 1e-12), c)
            ordered = sorted(customers, key=key)
        else:
            ordered = sorted(customers)
        routes = []
        route = []
        load = 0
        for c in ordered:
            d = demands.get(c, 0)
            if route and load + d > capacity:
                routes.append(route)
                route = [c]
                load = d
            else:
                route.append(c)
                load += d
        if route:
            routes.append(route)

    return routes
